import React from 'react';
import {Audio, Sequence, staticFile, useCurrentFrame, useVideoConfig, interpolate} from 'remotion';
import {SCENES, TOTAL_FRAMES, VO_SEGMENTS} from '../data/timeline';

const DUCK_ATTACK_FRAMES = Math.round(0.25 * 30); // 250ms
const DUCK_RELEASE_FRAMES = Math.round(0.5 * 30); // 500ms
const BGM_BASE = 0.5;
const BGM_DUCKED = 0.18;
const FADE_IN_FRAMES = 30;
const FADE_OUT_FRAMES = 45;

/**
 * 音频混音层：
 * - 12 段 VO（Edge TTS 女声）按时间轴播放
 * - BGM 全程垫底，VO 区间平滑 Ducking（attack 250ms / release 500ms），
 *   开场 fade in，结尾 fade out，自然 Resolution。
 * 原片人物音轨已被 ffmpeg -an 彻底移除（volume=0 等价）。
 */
export const AudioMix: React.FC = () => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();

  const voEls = SCENES.map((s) => {
    const fromFrame = Math.round((s.start + s.vo_offset) * fps);
    return (
      <Sequence key={s.vo} from={fromFrame} name={`vo-${s.vo}`}>
        <Audio src={staticFile(`audio/vo/${s.vo}.mp3`)} volume={1} />
      </Sequence>
    );
  });

  const bgmVolume = (f: number): number => {
    let v = BGM_BASE;
    for (const seg of VO_SEGMENTS) {
      const a = seg.start * fps;
      const b = seg.end * fps;
      if (f < a - DUCK_ATTACK_FRAMES || f > b + DUCK_RELEASE_FRAMES) continue;
      if (f < a) {
        v = Math.min(v, interpolate(f, [a - DUCK_ATTACK_FRAMES, a], [BGM_BASE, BGM_DUCKED], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'}));
      } else if (f <= b) {
        v = Math.min(v, BGM_DUCKED);
      } else {
        v = Math.min(v, interpolate(f, [b, b + DUCK_RELEASE_FRAMES], [BGM_DUCKED, BGM_BASE], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'}));
      }
    }
    v *= interpolate(f, [0, FADE_IN_FRAMES], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
    v *= interpolate(f, [TOTAL_FRAMES - FADE_OUT_FRAMES, TOTAL_FRAMES], [1, 0], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
    return v;
  };

  return (
    <>
      {voEls}
      <Audio src={staticFile('bgm.mp3')} volume={bgmVolume} />
    </>
  );
};

