import React from 'react';
import {AbsoluteFill, Sequence, useCurrentFrame} from 'remotion';
import {SCENES, VO_SEGMENTS} from '../data/timeline';
import {Background} from '../components/Background';
import {PresenterLayer} from '../components/PresenterLayer';
import {LaptopDemo} from '../components/LaptopDemo';
import {EvidenceScene} from '../components/EvidenceScene';
import {SemanticCaption} from '../components/SemanticCaption';
import {HeroScene} from '../components/HeroScene';
import {SummaryScene} from '../components/SummaryScene';
import {BrandEndCard} from '../components/BrandEndCard';
import {CapabilityTransition} from '../components/CapabilityTransition';
import {AudioMix} from '../components/AudioMix';

/**
 * XinShengPromo90｜Xin生智造 / EvoMind 90s 宣传片
 * 叙事：HOOK → 进入工作台 → 选角色/技能 → 下达任务 → AI执行 →
 *       文档交付 → 组织运营 → PPT → 数字大脑 → 知识追溯 → 品牌收束
 */
export const XinShengPromo90: React.FC = () => {
  const frame = useCurrentFrame();

  const S01 = SCENES[0];
  const S02 = SCENES[1];
  const S03 = SCENES[2];
  const S04 = SCENES[3];
  const S05 = SCENES[4];
  const S06 = SCENES[5];
  const S07 = SCENES[6];
  const S08 = SCENES[7];
  const S09 = SCENES[8];
  const S10 = SCENES[9];
  const S11 = SCENES[10];
  const S12 = SCENES[11];

  const caption = (s: (typeof SCENES)[number]) => {
    const from = s.start + s.vo_offset + 0.05;
    const to = s.start + s.duration - 0.15;
    return <SemanticCaption key={`cap-${s.id}`} text={s.caption} from={from} to={to} />;
  };

  return (
    <AbsoluteFill style={{background: '#EAF3FF'}}>
      {/* 全局背景（常驻） */}
      <Background />

      {/* ===== S01 HOOK ===== */}
      <Sequence from={0} durationInFrames={Math.round(S01.duration * 30)} name="S01-hero">
        <HeroScene image={S01.source!} title="从创意" subtitle="到真实成果" />
        <PresenterLayer heightRatio={0.74} localTime={frame / 30} entrance />
        {caption(S01)}
      </Sequence>

      {/* ===== S02 进入工作台（电脑） ===== */}
      <Sequence from={Math.round(S02.start * 30)} durationInFrames={Math.round(S02.duration * 30)} name="S02-step1">
        <LaptopDemo clips={S02.clips!} laptopWidth={1400} x={470} y={120} entrance />
        <PresenterLayer heightRatio={0.7} localTime={frame / 30} />
        {caption(S02)}
      </Sequence>

      {/* ===== S03 选择角色/智能体/技能（电脑 + 能力标签） ===== */}
      <Sequence from={Math.round(S03.start * 30)} durationInFrames={Math.round(S03.duration * 30)} name="S03-step2">
        <LaptopDemo clips={S03.clips!} laptopWidth={1320} x={500} y={130} entrance />
        <PresenterLayer heightRatio={0.68} localTime={frame / 30} />
        <CapabilityTransition
          items={['市场分析', 'PPT生成', '文档处理', '图片创作']}
          appearFrom={S03.start + 1.2}
          visibleUntil={S03.start + S03.duration - 0.3}
        />
        {caption(S03)}
      </Sequence>

      {/* ===== S04 下达任务（电脑） ===== */}
      <Sequence from={Math.round(S04.start * 30)} durationInFrames={Math.round(S04.duration * 30)} name="S04-step3">
        <LaptopDemo clips={S04.clips!} laptopWidth={1400} x={470} y={110} entrance />
        <PresenterLayer heightRatio={0.7} localTime={frame / 30} />
        {caption(S04)}
      </Sequence>

      {/* ===== S05 AI 执行（电脑） ===== */}
      <Sequence from={Math.round(S05.start * 30)} durationInFrames={Math.round(S05.duration * 30)} name="S05-exec">
        <LaptopDemo clips={S05.clips!} laptopWidth={1440} x={440} y={100} entrance />
        <PresenterLayer heightRatio={0.68} localTime={frame / 30} />
        {caption(S05)}
      </Sequence>

      {/* ===== S06 文档交付（大画幅） ===== */}
      <Sequence from={Math.round(S06.start * 30)} durationInFrames={Math.round(S06.duration * 30)} name="S06-doc">
        <EvidenceScene clips={S06.clips!} widthRatio={0.9} entrance />
        {caption(S06)}
      </Sequence>

      {/* ===== S07 组织运营看板（大画幅） ===== */}
      <Sequence from={Math.round(S07.start * 30)} durationInFrames={Math.round(S07.duration * 30)} name="S07-ops">
        <EvidenceScene clips={S07.clips!} widthRatio={0.9} entrance />
        {caption(S07)}
      </Sequence>

      {/* ===== S08 PPT（全屏） ===== */}
      <Sequence from={Math.round(S08.start * 30)} durationInFrames={Math.round(S08.duration * 30)} name="S08-ppt">
        <EvidenceScene clips={S08.clips!} fullscreen entrance />
        {caption(S08)}
      </Sequence>

      {/* ===== S09 团队数字大脑（全屏） ===== */}
      <Sequence from={Math.round(S09.start * 30)} durationInFrames={Math.round(S09.duration * 30)} name="S09-brain">
        <EvidenceScene clips={S09.clips!} fullscreen entrance />
        {caption(S09)}
      </Sequence>

      {/* ===== S10 知识追溯（全屏） ===== */}
      <Sequence from={Math.round(S10.start * 30)} durationInFrames={Math.round(S10.duration * 30)} name="S10-trace">
        <EvidenceScene clips={S10.clips!} fullscreen entrance />
        {caption(S10)}
      </Sequence>

      {/* ===== S11 总结 ===== */}
      <Sequence from={Math.round(S11.start * 30)} durationInFrames={Math.round(S11.duration * 30)} name="S11-summary">
        <SummaryScene stills={S11.stills!} keywords={['协作', '执行', '沉淀', '追溯']} />
        <PresenterLayer heightRatio={0.72} localTime={frame / 30} entrance />
        {caption(S11)}
      </Sequence>

      {/* ===== S12 品牌收束 ===== */}
      <Sequence from={Math.round(S12.start * 30)} durationInFrames={Math.round(S12.duration * 30)} name="S12-brand">
        <BrandEndCard
          image={S12.source!}
          brandLine1="Xin生智造"
          brandLine2="具身智能Xin苗启航营"
          brandLine3="Powered by 云知师AI / EvoMind"
        />
        <PresenterLayer heightRatio={0.74} localTime={frame / 30} entrance />
        {caption(S12)}
      </Sequence>

      {/* ===== 音频（VO + BGM ducking） ===== */}
      <AudioMix />
    </AbsoluteFill>
  );
};

export const voSegments = VO_SEGMENTS;

