import React from 'react';
import {createRoot} from 'react-dom/client';
import {Player} from '@remotion/player';
import {XinShengPromo90} from '../compositions/XinShengPromo90';
import {FPS, TOTAL_FRAMES, WIDTH, HEIGHT, SCENES, TOTAL_DURATION_S} from '../data/timeline';

const BUILD_ID = 'XinSheng-V1-20260827-1200';

const App: React.FC = () => {
  const sceneList = SCENES.map((s) => `${s.id}(${s.duration.toFixed(1)}s)`).join(' · ');

  return (
    <>
      <Player
        component={XinShengPromo90}
        durationInFrames={TOTAL_FRAMES}
        fps={FPS}
        compositionWidth={WIDTH}
        compositionHeight={HEIGHT}
        style={{width: '100%', aspectRatio: '16 / 9'}}
        controls
        loop
        autoPlay
        clickToPlay
        doubleClickToFullscreen
        acknowledgeRemotionLicense
      />
      <div>
        <b>Build ID:</b> {BUILD_ID} &nbsp;|&nbsp; <b>时长:</b> {TOTAL_DURATION_S}s / {TOTAL_FRAMES}f @ {FPS}fps &nbsp;|&nbsp;{' '}
        <b>Scene:</b> {sceneList}
        <br />
        <b>QA 状态:</b> Still 检查进行中（Opening / STEP1 / STEP2 / 文档交付 / PPT / 数字大脑 / 知识追溯 / Brand Close）——全部 PASS 后此 Player 才对外返回。
        <br />
        <b>注意:</b> 原人物音轨已全部移除；女声正文 1.3×、片尾 1.0×；BGM 自动 Ducking；无隐私片段（352–375.5s 已禁用）。
      </div>
    </>
  );
};

const container = document.getElementById('player')!;
const root = createRoot(container);
root.render(<App />);

// meta
document.getElementById('buildId')!.textContent = BUILD_ID;
const meta = document.getElementById('meta')!;
meta.innerHTML = `<b>Build ID:</b> ${BUILD_ID} &nbsp;|&nbsp; <b>时长:</b> ${TOTAL_DURATION_S}s (${TOTAL_FRAMES}f @ ${FPS}fps) &nbsp;|&nbsp; <b>Scene:</b> ${sceneList}`;

import React from 'react';
import {AbsoluteFill, Img, interpolate, staticFile, useCurrentFrame, useVideoConfig} from 'remotion';
import {FONT_FAMILY, WIDTH} from '../data/timeline';

/**
 * S11 总结场景：三张关键证据图轮播 + 能力关键词。
 */
export const SummaryScene: React.FC<{
  stills: string[];
  keywords: string[];
}> = ({stills, keywords}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const per = Math.round((7.0 * fps) / stills.length);

  return (
    <AbsoluteFill style={{zIndex: 25}}>
      {/* still carousel on the right */}
      <div
        style={{
          position: 'absolute',
          right: 60,
          top: 110,
          width: 1150,
          height: 700,
          borderRadius: 24,
          overflow: 'hidden',
          boxShadow: '0 26px 70px rgba(50,90,190,0.32)',
          background: '#fff',
        }}
      >
        {stills.map((s, i) => {
          const local = frame - i * per;
          const opacity = interpolate(local, [0, 12, per - 12, per], [0, 1, 1, 0], {
            extrapolateLeft: 'clamp',
            extrapolateRight: 'clamp',
          });
          const scale = interpolate(local, [0, per], [1.05, 1], {
            extrapolateLeft: 'clamp',
            extrapolateRight: 'clamp',
          });
          return (
            <div
              key={i}
              style={{
                position: 'absolute',
                inset: 0,
                opacity,
                transform: `scale(${scale})`,
              }}
            >
              <Img src={staticFile(s)} style={{width: '100%', height: '100%', objectFit: 'cover'}} />
            </div>
          );
        })}
      </div>

      {/* keywords left */}
      <div
        style={{
          position: 'absolute',
          left: 84,
          top: 200,
          width: 560,
          display: 'flex',
          flexDirection: 'column',
          gap: 26,
        }}
      >
        {keywords.map((k, i) => {
          const appear = interpolate(frame, [6 + i * 14, 6 + i * 14 + 12], [0, 1], {
            extrapolateLeft: 'clamp',
            extrapolateRight: 'clamp',
          });
          return (
            <div
              key={k}
              style={{
                opacity: appear,
                transform: `translateX(${(1 - appear) * -30}px)`,
                display: 'flex',
                alignItems: 'center',
                gap: 18,
              }}
            >
              <div
                style={{
                  width: 14,
                  height: 14,
                  borderRadius: 999,
                  background: 'linear-gradient(135deg, #5B8DEF, #8E7CE8)',
                  boxShadow: '0 0 0 6px rgba(120,150,240,0.25)',
                }}
              />
              <div
                style={{
                  fontSize: 46,
                  fontFamily: FONT_FAMILY,
                  fontWeight: 700,
                  color: '#1E3E8C',
                  letterSpacing: 4,
                }}
              >
                {k}
              </div>
            </div>
          );
        })}
      </div>

      <div style={{position: 'absolute', left: 88, top: 130, fontSize: 26, fontFamily: FONT_FAMILY, fontWeight: 600, color: '#5A7BD0', letterSpacing: 2}}>
        AI 进入创新活动全过程
      </div>
    </AbsoluteFill>
  );
};

import React from 'react';
import {AbsoluteFill, interpolate, useCurrentFrame} from 'remotion';
import {FONT_FAMILY} from '../data/timeline';

/**
 * 能力标签转场（S03 技能库增强）：右侧竖排能力 chip。
 * 轻量装饰，不遮挡电脑主体。
 */
export const CapabilityTransition: React.FC<{
  items: string[];
  appearFrom: number;
  visibleUntil: number;
}> = ({items, appearFrom, visibleUntil}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();

  return (
    <AbsoluteFill style={{pointerEvents: 'none', zIndex: 22}}>
      {items.map((it, i) => {
        const appear = interpolate(frame, [appearFrom * fps + i * 12, appearFrom * fps + i * 12 + 10], [0, 1], {
          extrapolateLeft: 'clamp',
          extrapolateRight: 'clamp',
        });
        const vanish = interpolate(frame, [visibleUntil * fps - 14, visibleUntil * fps], [1, 0], {
          extrapolateLeft: 'clamp',
          extrapolateRight: 'clamp',
        });
        const opacity = Math.min(appear, vanish);
        return (
          <div
            key={it}
            style={{
              position: 'absolute',
              right: 60,
              top: 150 + i * 96,
              opacity,
              transform: `translateX(${(1 - appear) * 40}px)`,
              fontSize: 30,
              fontFamily: FONT_FAMILY,
              fontWeight: 600,
              color: '#FFFFFF',
              background: 'linear-gradient(135deg, rgba(74,124,220,0.92), rgba(130,110,230,0.92))',
              padding: '12px 26px',
              borderRadius: 14,
              boxShadow: '0 10px 26px rgba(70,110,210,0.35)',
              border: '1px solid rgba(255,255,255,0.4)',
              letterSpacing: 1,
            }}
          >
            {it}
          </div>
        );
      })}
    </AbsoluteFill>
